import argparse
import gc
import hashlib
import json
import statistics
import sys
import time
from collections import deque
from pathlib import Path
from types import ModuleType
from unittest.mock import patch

import mlx.core as mx
import numpy as np

from nanogpt_macbook import normalization
from nanogpt_macbook.benchmark import source_info
from nanogpt_macbook.engine import select_device

sys.path.insert(0, str(Path.cwd() / 'scripts'))
from compare_normalization import compare


BASE = Path(normalization.__file__).read_text()


def variant(name):
    source = BASE
    if name == 'packed':
        source = source.replace('output_names=["dx", "dw", "db"]', 'output_names=["dx", "partials"]')
        source = source.replace('dw[group * D + col] = w;', 'partials[group * D + col] = w;')
        source = source.replace('db[group * D + col] = b;', 'partials[((N + R - 1) / R + group) * D + col] = b;')
        source = source.replace('dx, dw, db = backward(', 'dx, partials = backward(')
        source = source.replace('output_shapes=[x.shape, (groups, width), (groups, width)]', 'output_shapes=[x.shape, (2, groups, width)]')
        source = source.replace('output_dtypes=[mx.float32] * 3', 'output_dtypes=[mx.float32] * 2')
        source = source.replace('return dx, mx.sum(dw, axis=0), mx.sum(db, axis=0)', 'gradients = mx.sum(partials, axis=1)\n        return dx, gradients[0], gradients[1]')
    else:
        simds = '(1 if width <= 128 else 8)' if name == 'adaptive' else int(name.removeprefix('fused'))
        source = source.replace('return dx, mx.sum(dw, axis=0), mx.sum(db, axis=0)', f'''dw, db = _reduce_kernel()(inputs=[dw, db], template=[("G", groups), ("D", width), ("S", {simds})], output_shapes=[(width,), (width,)], output_dtypes=[mx.float32] * 2, grid=(((width + 31) // 32) * {simds} * 32, 1, 1), threadgroup=({simds} * 32, 1, 1))
        return dx, dw, db''')
        source += '''
@lru_cache(maxsize=1)
def _reduce_kernel():
    return mx.fast.metal_kernel(
        name="nanogpt_layer_norm_both_gradients",
        input_names=["partial_w", "partial_b"],
        output_names=["dw", "db"],
        source="""
            uint lane = thread_index_in_simdgroup;
            uint simd = simdgroup_index_in_threadgroup;
            uint col = threadgroup_position_in_grid.x * 32 + lane;
            float w = 0, b = 0;
            for (uint row = simd; row < G; row += S) {
                if (col < D) {
                    w += partial_w[row * D + col];
                    b += partial_b[row * D + col];
                }
            }
            threadgroup float ws[S * 32], bs[S * 32];
            ws[simd * 32 + lane] = w;
            bs[simd * 32 + lane] = b;
            threadgroup_barrier(mem_flags::mem_threadgroup);
            if (simd == 0 && col < D) {
                w = 0; b = 0;
                for (uint s = 0; s < S; ++s) {
                    w += ws[s * 32 + lane];
                    b += bs[s * 32 + lane];
                }
                dw[col] = w;
                db[col] = b;
            }
        """,
    )
'''
    module = ModuleType('norm_' + name)
    exec(compile(source, str(Path(__file__)) + ':' + name, 'exec'), module.__dict__)
    return module, source


def micro(name, cls, rows, width):
    mx.random.seed(1337)
    layer = cls(width)
    x = mx.random.normal((rows, width))
    w = mx.random.normal((width,))
    b = mx.random.normal((width,))
    dy = mx.random.normal(x.shape)
    mx.eval(x, w, b, dy)

    def loss(x, w, b, dy):
        layer.weight, layer.bias = w, b
        return (layer(x) * dy).sum()

    step = mx.compile(mx.value_and_grad(loss, argnums=(0, 1, 2)))
    actual = step(x, w, b, dy)
    expected = mx.value_and_grad(lambda x, w, b: (mx.fast.layer_norm(x, w, b, layer.eps) * dy).sum(), argnums=(0, 1, 2))(x, w, b)
    checks = []
    for a, e in zip(actual[1], expected[1]):
        aa, ee = np.array(a), np.array(e)
        np.testing.assert_allclose(aa, ee, atol=6e-5, rtol=4e-5)
        checks.append(float(np.max(np.abs(aa-ee))))

    def run(n):
        pending = deque()
        start = time.perf_counter()
        for _ in range(n):
            out = step(x, w, b, dy)
            mx.async_eval(out)
            pending.append(out)
            if len(pending) == 2:
                mx.eval(pending.popleft())
        while pending:
            mx.eval(pending.popleft())
        mx.synchronize()
        return (time.perf_counter()-start)*1000/n
    run(20)
    timings = [run(300) for _ in range(5)]
    return dict(variant=name, rows=rows, width=width, median_ms=statistics.median(timings), repeat_ms=timings, gradient_max_abs_errors=checks)


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--out', type=Path, required=True)
    parser.add_argument('--full', choices=['packed', 'fused1', 'fused2', 'fused4', 'fused8', 'adaptive'])
    parser.add_argument('--pairs', type=int, default=8)
    parser.add_argument('--steps', type=int, default=100)
    args = parser.parse_args()
    assert not args.out.exists()
    select_device('gpu', 2)
    names = [args.full] if args.full else ['packed', 'fused1', 'fused2', 'fused4', 'fused8']
    variants = {name: variant(name) for name in names}
    record = dict(source=source_info(), runner_source=Path(__file__).read_text(), baseline_sha256=hashlib.sha256(BASE.encode()).hexdigest(), variants={name:dict(source=source,sha256=hashlib.sha256(source.encode()).hexdigest()) for name,(_,source) in variants.items()}, results=[])
    reference = normalization.LayerNorm.__call__
    if args.full:
        record['method'] = dict(scope='Complete training', pairs=args.pairs,steps=args.steps,warmup=20,queue=2,memory_gib=2,fresh=True)
        for preset in ['tiny', 'small', 'medium']:
            with patch.object(normalization.LayerNorm, '__call__', variants[args.full][0].LayerNorm.__call__):
                result = compare(preset,args.pairs,args.steps,20,reference=reference,queued=True,fresh=True)
            record['results'].append(result)
            args.out.write_text(json.dumps(record,indent=2)+'\n')
    else:
        record['method'] = dict(scope='Isolated LayerNorm forward and all gradients', warmup=20,steps=300,repeats=5,queue=2,memory_gib=2)
        for rows,width in [(1024,128),(2048,256),(2048,384)]:
            for name,cls in [('reference',normalization.LayerNorm)]+[(name,module.LayerNorm) for name,(module,_) in variants.items()]:
                result = micro(name,cls,rows,width)
                print(name,rows,width,round(result['median_ms'],4),'ms',flush=True)
                record['results'].append(result)
                args.out.write_text(json.dumps(record,indent=2)+'\n')
                gc.collect()
                mx.clear_cache()


if __name__ == '__main__':
    main()

